Here is the commit message:
IB/mthca: Add missed mthca_unmap_user_db() for
 mthca_create_srq()

Fix a user triggerable leak on the system call failure path.

Cc: stable@vger.kernel.org
Fixes: ec34a922d243 ("[PATCH] IB/mthca: Add SRQ implementation")
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>
Link: https://patch.msgid.link/2-v1-83e918d69e73+a9-rdma_udata_rc_jgg@nvidia.com
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
In `mthca_create_srq()`, when `ib_copy_to_udata()` fails in the error path, the function calls `mthca_free_srq()` but does not call `mthca_unmap_user_db()` to release the previously mapped user doorbell, causing a resource leak. Additionally, the destructive order in `mthca_destroy_srq()` is corrected to prevent a potential use-after-free, but the primary bug is the missing unmapping in the creation failure path.

Here is the patch:

 static int mthca_create_srq(struct ib_srq *ibsrq,
 			    struct ib_srq_init_attr *init_attr,
 			    struct ib_udata *udata)
 {
 	struct mthca_create_srq ucmd;
 	struct mthca_ucontext *context = rdma_udata_to_drv_context(
 		udata, struct mthca_ucontext, ibucontext);
 	struct mthca_srq *srq = to_msrq(ibsrq);
 	int err;

 	if (init_attr->srq_type != IB_SRQT_BASIC)
 		return -EOPNOTSUPP;

 	if (udata) {
 		if (ib_copy_from_udata(&ucmd, udata, sizeof(ucmd)))
 			return -EFAULT;

 		err = mthca_map_user_db(to_mdev(ibsrq->device), &context->uar,
 					context->db_tab, ucmd.db_index,
 					ucmd.db_page);

 		if (err)
 			return err;

 		srq->mr.ibmr.lkey = ucmd.lkey;
 		srq->db_index     = ucmd.db_index;
 	}

 	err = mthca_alloc_srq(to_mdev(ibsrq->device), to_mpd(ibsrq->pd),
 			      &init_attr->attr, srq, udata);

 	if (err && udata)
 		mthca_unmap_user_db(to_mdev(ibsrq->device), &context->uar,
 				    context->db_tab, ucmd.db_index);

 	if (err)
 		return err;

 	if (context && ib_copy_to_udata(udata, &srq->srqn, sizeof(__u32))) {
 		mthca_free_srq(to_mdev(ibsrq->device), srq);
+		mthca_unmap_user_db(to_mdev(ibsrq->device), &context->uar,
+				    context->db_tab, ucmd.db_index);
 		return -EFAULT;
 	}

 	return 0;
 }

 static int mthca_destroy_srq(struct ib_srq *srq, struct ib_udata *udata)
 {
+	mthca_free_srq(to_mdev(srq->device), to_msrq(srq));
 	if (udata) {
 		struct mthca_ucontext *context =
 			rdma_udata_to_drv_context(
 				udata,
 				struct mthca_ucontext,
 				ibucontext);

 		mthca_unmap_user_db(to_mdev(srq->device), &context->uar,
 				    context->db_tab, to_msrq(srq)->db_index);
 	}
-
-	mthca_free_srq(to_mdev(srq->device), to_msrq(srq));
 	return 0;
 }



